"use strict";

const fs = require("node:fs");

class ConfigError extends Error {}

function loadConfig(configPath) {
  let raw;
  try {
    raw = fs.readFileSync(configPath, "utf8");
  } catch (error) {
    if (error && error.code === "ENOENT") {
      const err = new ConfigError(`config file is missing: ${configPath}`);
      err.path = configPath;
      err.reason = "missing";
      throw err;
    }
    throw error;
  }
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    const err = new ConfigError(`config file is not valid JSON: ${configPath}`);
    err.path = configPath;
    err.reason = "invalid-json";
    throw err;
  }
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
    const err = new ConfigError(`config root must be an object: ${configPath}`);
    err.path = configPath;
    err.reason = "not-an-object";
    throw err;
  }
  return parsed;
}

module.exports = { ConfigError, loadConfig };
